        /// <summary>
        /// This method is used to fill disabled bank list.
        /// </summary>
        /// <param name="oSqlDataReader"></param>
        private void FillBankDetails(SqlDataReader oSqlDataReader)
        {
            DisbaleBankDetails oDisbaleBankDetails = null;
            RegBankDetails oRegBankDetails = null;
            while (oSqlDataReader.Read())
            {
                oRegBankDetails = new RegBankDetails()
                {
                    NetBankingBankId = Convert.ToInt32(oSqlDataReader["NetBankingBankId"]),
                    RegisterdBankName = oSqlDataReader["RegisterdBankName"].ToString()
                };
                oDisbaleBankDetails = new DisbaleBankDetails
                {
                    DisabledBankId = Convert.ToInt32(oSqlDataReader["DisabledBankId"]),
                    StartDateTime = Convert.ToDateTime(oSqlDataReader["StartDateTime"]),
                    EndDateTime = Convert.ToDateTime(oSqlDataReader["EndDateTime"]),
                    RuleStatus = oSqlDataReader["RuleStatus"].ToString(),
                    RegBankDetails = oRegBankDetails
                };
                mlstDisbaleBankDetails.Add(oDisbaleBankDetails);
            }
        }
